import tomllib
import os
from typing import Dict, Optional, Any


class ConfigError(Exception):
    """Exception raised for configuration errors."""
    def __init__(self, message: str):
        self.message = message
        super().__init__(self.message)


def coerce_string(value: str) -> str:
    return value


def coerce_int(value: str) -> int:
    try:
        return int(value)
    except ValueError:
        raise ConfigError(f"Expected integer, got '{value}'")


def coerce_float(value: str) -> float:
    try:
        return float(value)
    except ValueError:
        raise ConfigError(f"Expected float, got '{value}'")


def coerce_bool(value: str) -> bool:
    value_lower = value.lower()
    if value_lower in ('true', 'yes', '1'):
        return True
    elif value_lower in ('false', 'no', '0'):
        return False
    else:
        raise ConfigError(f"Expected boolean, got '{value}'")


def coerce_value(default_type: type, value: str) -> Any:
    """Coerce string value to the type of the default."""
    if default_type == int:
        return coerce_int(value)
    elif default_type == float:
        return coerce_float(value)
    elif default_type == bool:
        return coerce_bool(value)
    elif default_type == str:
        return coerce_string(value)
    else:
        raise ConfigError(f"Unsupported type: {default_type}")


def load_toml(toml_path: str) -> Dict[str, Any]:
    """Load TOML file if it exists."""
    if not os.path.exists(toml_path):
        return {}

    with open(toml_path, 'rb') as f:
        return tomllib.load(f)


